                msg.setId(rs.getLong("id"));
                msg.setChannel(Message.Channel.valueOf(rs.getString("channel")));
                msg.setTo(rs.getString("to_address"));
                msg.setSubject(rs.getString("subject"));
                msg.setBody(rs.getString("body"));
                messages.add(msg);
            }
        }
        return messages;
    }
}

